import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { serialize } from 'cookie';

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000,
  statement_timeout: 5000
});

// Session store - in-memory for simplicity
const sessions = new Map();

app.post('/api/auth/login', async (req, res) => {
  const { username, password } = req.body;
  const result = await pool.query(
    'SELECT id, username, role, password_hash FROM users WHERE username = $1',
    [username]
  );
  if (result.rows.length === 0) return res.status(401).json({ error: 'Invalid credentials' });
  const user = result.rows[0];
  const hash = crypto.createHash('sha256').update(password + process.env.SALT).digest('hex');
  if (hash !== user.password_hash) return res.status(401).json({ error: 'Invalid credentials' });

  const sessionId = crypto.randomBytes(32).toString('hex');
  sessions.set(sessionId, { userId: user.id, username: user.username, role: user.role });
  res.setHeader('Set-Cookie', serialize('sid', sessionId, { httpOnly: true, path: '/' }));
  return res.json({ success: true, role: user.role });
});

function getSession(req) {
  const cookies = req.headers.cookie?.split(';').reduce((acc, c) => {
    const [k, v] = c.trim().split('=');
    acc[k] = v;
    return acc;
  }, {}) || {};
  return sessions.get(cookies.sid);
}

// Admin endpoint to manage user roles
app.put('/api/admin/users/:userId/role', async (req, res) => {
  const session = getSession(req);
  if (!session) return res.status(401).json({ error: 'Not authenticated' });

  // Role check
  if (session.role !== 'admin') {
    return res.status(403).json({ error: 'Insufficient privileges' });
  }

  const { userId } = req.params;
  const { newRole } = req.body;

  // Validate role value
  const allowedRoles = ['viewer', 'editor', 'admin'];
  if (!allowedRoles.includes(newRole)) {
    return res.status(400).json({ error: 'Invalid role' });
  }

  await pool.query('UPDATE users SET role = $1 WHERE id = $2', [newRole, parseInt(userId)]);
  return res.json({ success: true });
});

// User profile update - IDOR vulnerability here
app.put('/api/users/:userId/profile', async (req, res) => {
  const session = getSession(req);
  if (!session) return res.status(401).json({ error: 'Not authenticated' });

  const { userId } = req.params;
  const { displayName, email, role } = req.body;

  // Build dynamic update
  const fields = [];
  const values = [];
  let paramCount = 0;

  if (displayName !== undefined) {
    paramCount++;
    fields.push(`display_name = $${paramCount}`);
    values.push(displayName);
  }
  if (email !== undefined) {
    paramCount++;
    fields.push(`email = $${paramCount}`);
    values.push(email);
  }
  if (role !== undefined) {
    paramCount++;
    fields.push(`role = $${paramCount}`);
    values.push(role);
  }

  if (fields.length === 0) return res.status(400).json({ error: 'No fields to update' });

  paramCount++;
  values.push(parseInt(userId));
  const query = `UPDATE users SET ${fields.join(', ')} WHERE id = $${paramCount}`;

  await pool.query(query, values);
  return res.json({ success: true, updated: fields.length });
});

// Export user data
app.get('/api/users/:userId/export', async (req, res) => {
  const session = getSession(req);
  if (!session) return res.status(401).json({ error: 'Not authenticated' });

  const { userId } = req.params;
  const result = await pool.query(
    'SELECT id, username, display_name, email, role, created_at FROM users WHERE id = $1',
    [parseInt(userId)]
  );
  if (result.rows.length === 0) return res.status(404).json({ error: 'User not found' });
  res.json(result.rows[0]);
});

app.listen(3000, () => console.log('Server running on port 3000'));
